/** 📐️ Nine actual CAD geometries and independent layer/block foreign-key queries. */
import {Database} from "bun:sqlite";
import {expect,test} from "bun:test";
import f from "../🧫️fixtures/🔣️.json";
import type {SemioCadSnapshot,CadEntity} from "../../../../🧬️schema/📸️snapshot/🟦️.ts";
import {SEMIO_CAD_SQLITE_SCHEMA,semioCadSnapshotToSqliteDatabase,semioCadSnapshotFromSqliteDatabase} from "../🟦️.ts";
import {binary64,exportSqliteDatabase,importSqliteDatabase} from "@semio-tech/framework";
const point=(x=1,y=2)=>({x:binary64(x),y:binary64(y)});
const geometries:CadEntity[]=[{kind:"line",a:point(),b:point(3,4)},{kind:"arc",center:point(),radius:binary64(f.radius),startAngle:binary64(f.startAngle),endAngle:binary64(f.endAngle)},{kind:"circle",center:point(),radius:binary64(f.radius)},{kind:"ellipse",center:point(),majorAxisEnd:point(3,4),ratio:binary64(f.ratio),startParam:binary64(-1),endParam:binary64(2)},{kind:"polyline",vertices:[point(),point(3,4)],closed:true},{kind:"text",position:point(),height:binary64(3),rotation:binary64(-1),content:f.text},{kind:"insert",blockName:f.blockName,insertionPoint:point(),scale:point(2,3),rotation:binary64(1)},{kind:"solid",p1:point(),p2:point(3,4),p3:point(5,6),p4:point(7,8)},{kind:"dimension",defPoint:point(),textPosition:point(3,4),measurement:binary64(5),text:f.text}];
const input:SemioCadSnapshot={schema:f.schema,layers:f.layerNames.map((name,i)=>({name,colorIndex:f.colorIndices[i]!,lineType:f.lineTypes[i]!,visible:i===0})),blocks:[{name:f.blockName,basePoint:point(...f.blockBase as[number,number]),entities:[{handle:"0",layer:f.layerNames[1]!,entity:{kind:"line",a:point(),b:point(3,4)}}]}],entities:geometries.map((entity,i)=>({handle:String(i),layer:f.layerNames[i%2]!,entity}))};
test("Semio CAD independent variant geometry queries and edited text",async()=>{expect(SEMIO_CAD_SQLITE_SCHEMA).toBe(await Bun.file(new URL("../🗄️.sql",import.meta.url)).text());const db=Database.deserialize(await exportSqliteDatabase(await semioCadSnapshotToSqliteDatabase(input)));try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query(f.query).all()).toHaveLength(1);expect(await semioCadSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(input);db.query("UPDATE semio_cad_text SET content='independent'").run();const edited=structuredClone(input),entity=edited.entities[5]!.entity;if(entity.kind!=="text")throw Error("fixture text");entity.content="independent";expect(await semioCadSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(edited);}finally{db.close();}});
test("quick::Semio CAD exact IEEE words, variant ownership, limits and cancellation",async()=>{for(const hex of f.float64Bits){const s=structuredClone(input),w={bits:BigInt("0x"+hex)};s.blocks[0]!.basePoint={x:w,y:w};s.entities[0]!.entity={kind:"line",a:{x:w,y:w},b:{x:w,y:w}};s.entities[1]!.entity={kind:"arc",center:{x:w,y:w},radius:w,startAngle:w,endAngle:w};s.entities[2]!.entity={kind:"circle",center:{x:w,y:w},radius:w};s.entities[3]!.entity={kind:"ellipse",center:{x:w,y:w},majorAxisEnd:{x:w,y:w},ratio:w,startParam:w,endParam:w};s.entities[4]!.entity={kind:"polyline",vertices:[{x:w,y:w}],closed:false};s.entities[5]!.entity={kind:"text",position:{x:w,y:w},height:w,rotation:w,content:""};s.entities[6]!.entity={kind:"insert",blockName:f.blockName,insertionPoint:{x:w,y:w},scale:{x:w,y:w},rotation:w};s.entities[7]!.entity={kind:"solid",p1:{x:w,y:w},p2:{x:w,y:w},p3:{x:w,y:w},p4:{x:w,y:w}};s.entities[8]!.entity={kind:"dimension",defPoint:{x:w,y:w},textPosition:{x:w,y:w},measurement:w,text:""};const db=Database.deserialize(await exportSqliteDatabase(await semioCadSnapshotToSqliteDatabase(s)));try{expect(await semioCadSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(s);}finally{db.close();}}const d=await semioCadSnapshotToSqliteDatabase(input);for(const mutate of[(x:any)=>x.tables[3].rows[0].values[5]=999n,(x:any)=>x.tables[11].rows[0].values[1]=999n,(x:any)=>x.tables[9].rows[0].values[1]=999n,(x:any)=>x.tables[3].rows[0].values[6]="circle",(x:any)=>x.tables[1].rows[0].values[4]=2147483648n]){const x=structuredClone(d);mutate(x);await expect(semioCadSnapshotFromSqliteDatabase(x)).rejects.toThrow();}await expect(semioCadSnapshotToSqliteDatabase(input,{maxRows:1})).rejects.toThrow();await expect(semioCadSnapshotFromSqliteDatabase(d,{maxValueBytes:1})).rejects.toThrow();const c=new AbortController();c.abort();await expect(semioCadSnapshotFromSqliteDatabase(d,{signal:c.signal})).rejects.toThrow();},30000);

test("Semio CAD native construction frontier independently preserves layer joins and line ordinals",async()=>{const s:SemioCadSnapshot={schema:f.schema,layers:input.layers,blocks:[],entities:Array.from({length:f.nativeAdmission.collectionItems},(_,index)=>({handle:`line-${index}`,layer:"visible",entity:{kind:"line",a:point(-0,0),b:point(1,1)}}))};const d=Database.deserialize(await exportSqliteDatabase(await semioCadSnapshotToSqliteDatabase(s)));try{expect(d.query("SELECT count(*) AS count FROM semio_cad_line").get()).toEqual({count:f.nativeAdmission.collectionItems});expect(d.query("SELECT handle,l.name AS layer FROM semio_cad_entity e JOIN semio_cad_layer l ON e.layer_id=l.id WHERE e.ordinal=?").get(f.nativeAdmission.cancelAfter)).toEqual({handle:`line-${f.nativeAdmission.cancelAfter}`,layer:"visible"});}finally{d.close();}});

import completeSemanticContract from "../🧫️fixtures/🎛️semantic.json";
import completeSemanticSchema from "../🧫️fixtures/🧬️semantic.json";
import Ajv2020Complete from "ajv/dist/2020";
import{independentSqliteExtent as completeIndependentExtent}from "../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🧪️tests/🔮️semantic-extent/🟦️.ts";
test("Semio CAD Native matched full and metadata empty independently preserve all complete cells",async()=>{
 expect(new Ajv2020Complete({strict:true}).compile(completeSemanticSchema)(completeSemanticContract)).toBe(true);
 for(const item of completeSemanticContract.cases){const source=structuredClone(item.sourceSnapshot)as unknown as SemioCadSnapshot;const hydrate=(value:unknown):unknown=>Array.isArray(value)?value.map(hydrate):value!==null&&typeof value==="object"?("bits"in value?{bits:String((value as {bits:string}).bits).length===8?Number.parseInt(String((value as {bits:string}).bits),16):BigInt("0x"+String((value as {bits:string}).bits))}:Object.fromEntries(Object.entries(value).map(([key,item])=>[key,hydrate(item)]))):value;Object.assign(source,hydrate(source));const database=await semioCadSnapshotToSqliteDatabase(source),bytes=await exportSqliteDatabase(database);expect(completeIndependentExtent(bytes)).toEqual({rows:item.rows,valueBytes:item.valueBytes,schemaBytes:completeSemanticContract.schemaBytes,tableWidths:completeSemanticContract.tableWidths});const limits={maxRows:item.rows,maxValueBytes:item.valueBytes,maxSchemaBytes:completeSemanticContract.schemaBytes,maxTables:14,maxColumns:25};expect(await semioCadSnapshotToSqliteDatabase(source,limits)).toEqual(database);expect(await semioCadSnapshotFromSqliteDatabase(await importSqliteDatabase(bytes),limits)).toEqual(source);
 for(const short of[{...limits,maxRows:item.rows-1},{...limits,maxValueBytes:item.valueBytes-1},{...limits,maxSchemaBytes:limits.maxSchemaBytes-1},{...limits,maxTables:13},{...limits,maxColumns:24}]){await expect(semioCadSnapshotToSqliteDatabase(source,short)).rejects.toThrow();await expect(semioCadSnapshotFromSqliteDatabase(database,short)).rejects.toThrow();}
 }console.log("[DEBUG] Semio CAD independently measured Native matched full and empty roles through all5 copied limits");
});

