/** 🔺️ Neutral mesh buffers and independently queried indexed vertex relationships. */
import {parseDsl,parsePack,printDsl,packBytes,applyMutation,inverseMutation} from "../../../../🧪️tests/🔺️mutate-semio-mesh/🟦️.ts";
import {NodeIO} from "@gltf-transform/core";
import textureFixture from "../../../../🧬️schema/📸️snapshot/🧫️fixtures/🎨️material-textures/🔣️.json";
import {Database} from "bun:sqlite";
import {expect,test} from "bun:test";
import f from "../🧫️fixtures/🔣️.json";
import type {SemioMeshSnapshot,SemioTopology} from "../../../../🧬️schema/📸️snapshot/🟦️.ts";
import {SEMIO_MESH_SQLITE_SCHEMA,semioMeshSnapshotToSqliteDatabase,semioMeshSnapshotFromSqliteDatabase} from "../🟦️.ts";
import {binary64,binary32,exportSqliteDatabase,importSqliteDatabase} from "@semio-tech/framework";
const topologies:SemioTopology[]=["points","lines","lineStrip","triangles","triangleStrip","triangleFan"];
const point=(v:readonly number[])=>({x:binary64(v[0]!),y:binary64(v[1]!),z:binary64(v[2]!)}),color=(v:readonly number[])=>({r:binary32(v[0]!),g:binary32(v[1]!),b:binary32(v[2]!),a:binary32(v[3]!)});
const input:SemioMeshSnapshot={schema:f.schema,materials:[{id:f.materialId,baseColor:color(f.colors[0]!),metallic:binary32(f.metallic),roughness:binary32(f.roughness),...f.materialTextures}],textures:[{id:f.textureId,mime:f.mime,bytes:[0,1,255]}],meshes:[{id:f.meshId,primitives:topologies.map((topology,i)=>({id:String(i),topology,positions:f.positions.map(point),normals:[point(f.normal)],uvs:f.uvs.map(v=>({u:binary64(v[0]!),v:binary64(v[1]!)})),colors:f.colors.map(color),indices:f.indices.slice(),materialId:i%2===0?f.materialId:null}))}]};
test("Semio Mesh independent typed joins and genuine texture bytes",async()=>{expect(SEMIO_MESH_SQLITE_SCHEMA).toBe(await Bun.file(new URL("../🗄️.sql",import.meta.url)).text());const db=Database.deserialize(await exportSqliteDatabase(await semioMeshSnapshotToSqliteDatabase(input)));try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query(f.query).all()).toHaveLength(18);expect(db.query(f.materialTextureQuery).get()).toEqual(f.materialTextures);expect(await semioMeshSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(input);db.query("UPDATE semio_mesh_texture SET bytes=X'ff00'").run();const edited=structuredClone(input);edited.textures[0]!.bytes=[255,0];expect(await semioMeshSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(edited);}finally{db.close();}});
test("quick::Semio Mesh all native float words, index ownership and bounds",async()=>{for(let i=0;i<f.float64Bits.length;i++){const s=structuredClone(input),word64={bits:BigInt("0x"+f.float64Bits[i]!)},word32={bits:parseInt(f.float32Bits[i]!,16)},p=s.meshes[0]!.primitives[0]!;p.positions[0]={x:word64,y:word64,z:word64};p.normals[0]={x:word64,y:word64,z:word64};p.uvs[0]={u:word64,v:word64};p.colors[0]={r:word32,g:word32,b:word32,a:word32};s.materials[0]!.baseColor={r:word32,g:word32,b:word32,a:word32};s.materials[0]!.metallic=word32;s.materials[0]!.roughness=word32;const db=Database.deserialize(await exportSqliteDatabase(await semioMeshSnapshotToSqliteDatabase(s)));try{expect(await semioMeshSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(s);}finally{db.close();}}const d=await semioMeshSnapshotToSqliteDatabase(input);for(const mutate of[(x:any)=>x.tables[7].rows[0].values[3]=4294967296n,(x:any)=>x.tables[2].rows[0].values[5]=999n,(x:any)=>x.tables[3].rows[0].values[1]=999n,(x:any)=>x.tables[3].rows[0].values[2]=1n]){const x=structuredClone(d);mutate(x);await expect(semioMeshSnapshotFromSqliteDatabase(x)).rejects.toThrow();}const bad=structuredClone(input);bad.meshes[0]!.primitives[0]!.indices=[4294967296];await expect(semioMeshSnapshotToSqliteDatabase(bad)).rejects.toThrow();await expect(semioMeshSnapshotToSqliteDatabase(input,{maxRows:1})).rejects.toThrow();await expect(semioMeshSnapshotFromSqliteDatabase(d,{maxValueBytes:1})).rejects.toThrow();const c=new AbortController();c.abort();await expect(semioMeshSnapshotFromSqliteDatabase(d,{signal:c.signal})).rejects.toThrow();},30000);

test("Semio Mesh texture budget includes named-row overhead before source octet copies",async()=>{let reads=0;const bytes=new Proxy(Array<number>(100000).fill(0),{get(target,key,receiver){if(typeof key==="string"&&/^[0-9]+$/.test(key))reads++;return Reflect.get(target,key,receiver);}}),s:SemioMeshSnapshot={schema:"",meshes:[],materials:[],textures:[{id:"é",mime:"µ",bytes}]};await expect(semioMeshSnapshotToSqliteDatabase(s,{maxValueBytes:100031})).rejects.toThrow();expect(reads).toBe(0);const c=new AbortController();await expect(semioMeshSnapshotToSqliteDatabase(s,{signal:c.signal,onProgress(p){if(p.phase==="projectSnapshot"&&p.total===bytes.length)c.abort();}})).rejects.toThrow();expect(reads).toBe(0);});

test("Semio mesh native construction frontier independently preserves signed-zero position words",async()=>{const s:SemioMeshSnapshot={schema:f.schema,meshes:[{id:"mesh",primitives:[{id:"points",topology:"points",positions:Array.from({length:f.nativeAdmission.collectionItems},()=>({x:binary64(-0),y:binary64(0),z:binary64(1)})),normals:[],uvs:[],colors:[],indices:[],materialId:null}]}],materials:[],textures:[]};const d=Database.deserialize(await exportSqliteDatabase(await semioMeshSnapshotToSqliteDatabase(s)));try{expect(d.query("SELECT count(*) AS count FROM semio_mesh_position").get()).toEqual({count:f.nativeAdmission.collectionItems});expect(d.query("SELECT x_numeric_class FROM semio_mesh_position WHERE ordinal=?").get(f.nativeAdmission.cancelAfter)).toEqual({x_numeric_class:"finite"});expect(d.query("SELECT CAST(x_ieee754_bits AS TEXT) AS bits FROM semio_mesh_position WHERE ordinal=?").get(f.nativeAdmission.cancelAfter)).toEqual({bits:"-9223372036854775808"});}finally{d.close();}});

test("Semio Mesh retains unresolved material texture names and preserves explicit clearing",async()=>{const s=structuredClone(input);s.materials[0]!.normalTexture="missing";expect(await semioMeshSnapshotFromSqliteDatabase(await semioMeshSnapshotToSqliteDatabase(s))).toEqual(s);const d:any=await semioMeshSnapshotToSqliteDatabase(input);d.tables[8]!.rows[0]!.values[10]=999n;await expect(semioMeshSnapshotFromSqliteDatabase(d)).rejects.toThrow();const cleared=structuredClone(input);cleared.materials[0]!.normalTexture=null;expect(await semioMeshSnapshotFromSqliteDatabase(await semioMeshSnapshotToSqliteDatabase(cleared))).toEqual(cleared);console.log("[DEBUG] Semio material literal texture joins, storage refusal and clear validated");});

test("Semio material neutral glTF bindings match the independent source-image reader",async()=>{const document=await new NodeIO().readJSON({json:structuredClone(textureFixture.gltf),resources:{}}),material=document.getRoot().listMaterials()[0]!;const samples=[material.getBaseColorTexture(),material.getMetallicRoughnessTexture(),material.getNormalTexture(),material.getOcclusionTexture(),material.getEmissiveTexture()];for(const[index,key]of Object.keys(textureFixture.bindings).entries()){const source=Number(textureFixture.bindings[key as keyof typeof textureFixture.bindings].slice(4));expect(Array.from(samples[index]!.getImage()!)).toEqual(textureFixture.textureBytes[source]!);}console.log("[DEBUG] Five glTF texture slots resolve permuted source PNG bytes through glTF Transform");});

test("Semio material texture IDs survive both authored carriers and the existing mutation owner",async()=>{for(const base of ["../../../../🧫️fixtures/🔺️mutate-semio-mesh","../../../../📚️examples/🧊️cube/🖼️assets"]){const text=await Bun.file(new URL(base+"/🗣️.dsl.semio",import.meta.url)).text(),bytes=new Uint8Array(await Bun.file(new URL(base+"/🎒️.pack.semio",import.meta.url)).arrayBuffer()),snapshot=parseDsl(text);expect(parsePack(bytes)).toEqual(snapshot);expect(printDsl(snapshot)).toBe(text);expect(packBytes(snapshot)).toEqual(bytes);}const snapshot=parseDsl(await Bun.file(new URL("../../../../🧫️fixtures/🔺️mutate-semio-mesh/🗣️.dsl.semio",import.meta.url)).text());const material=snapshot.materials[0]!;Object.assign(material,textureFixture.bindings);snapshot.textures=textureFixture.textureBytes.map((bytes,i)=>({id:`tex-${i}`,mime:"image/png",bytes}));expect(parseDsl(printDsl(snapshot))).toEqual(snapshot);expect(parsePack(packBytes(snapshot))).toEqual(snapshot);expect(()=>applyMutation(snapshot,{DeleteTexture:{id:"tex-2"}})).toThrow("target-referenced");snapshot.textures.unshift({id:"unused",mime:"image/png",bytes:[]});const mutation={DeleteTexture:{id:"unused"}},after=applyMutation(snapshot,mutation);let restored=after;for(const undo of inverseMutation(snapshot,mutation))restored=applyMutation(restored,undo);expect(restored).toEqual(snapshot);console.log("[DEBUG] Authored DSL/pack assets, five texture IDs and position-preserving undo validated");});


test("Semio Mesh code-admitted intermediate owner survives independently queried physical SQLite",async()=>{
 const neutral=await Bun.file(new URL("../🧫️fixtures/🧩️intermediate/🔣️.json",import.meta.url)).json();
 const {default:Ajv}=await import("ajv");expect(neutral["role"]).toEqual("codeAdmittedIntermediateOwner");expect(neutral["snapshot"]).toEqual({"schema":"mesh\u0000世界","meshes":[{"id":"mesh","primitives":[{"id":"primitive","topology":"points","positions":[],"normals":[],"uvs":[],"colors":[],"indices":[4294967295],"materialId":"unmatched-material\u0000世界"}]}],"materials":[{"id":"material","baseColor":{"r":0,"g":0,"b":0,"a":0},"metallic":0,"roughness":0,"baseColorTexture":"unmatched-base","metallicRoughnessTexture":"unmatched-metallic","normalTexture":"unmatched-normal","occlusionTexture":"unmatched-occlusion","emissiveTexture":"unmatched-emissive"}],"textures":[]});expect(neutral["query"]).toEqual("SELECT vertex_index FROM semio_mesh_index ORDER BY ordinal");expect(neutral["expectedRows"]).toEqual([{"vertex_index":4294967295}]);
 const input=structuredClone(neutral.snapshot);for(const material of input.materials){for(const key of ["r","g","b","a"] as const)material.baseColor[key]=binary32(material.baseColor[key]);material.metallic=binary32(material.metallic);material.roughness=binary32(material.roughness);}
 const db=Database.deserialize(await exportSqliteDatabase(await semioMeshSnapshotToSqliteDatabase(input)));
 try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query(neutral.query).all()).toEqual(neutral.expectedRows);expect(await semioMeshSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(input);db.query("UPDATE semio_mesh_primitive SET material_native_id=?").run("independently edited");input.meshes[0].primitives[0].materialId="independently edited";expect(await semioMeshSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(input);console.log("[DEBUG] Semio mesh independently retains unresolved material and five texture names plus empty positions and raw u32 maximum indices");}finally{db.close();}
});

import completeSemanticContract from "../🧫️fixtures/🎛️semantic.json";
import completeSemanticSchema from "../🧫️fixtures/🧬️semantic.json";
import Ajv2020Complete from "ajv/dist/2020";
import{independentSqliteExtent as completeIndependentExtent}from "../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🧪️tests/🔮️semantic-extent/🟦️.ts";
test("Semio Mesh Native matched full and metadata empty independently preserve all complete cells",async()=>{
 expect(new Ajv2020Complete({strict:true}).compile(completeSemanticSchema)(completeSemanticContract)).toBe(true);
 for(const item of completeSemanticContract.cases){const source=structuredClone(item.sourceSnapshot)as unknown as SemioMeshSnapshot;const hydrate=(value:unknown):unknown=>Array.isArray(value)?value.map(hydrate):value!==null&&typeof value==="object"?("bits"in value?{bits:String((value as {bits:string}).bits).length===8?Number.parseInt(String((value as {bits:string}).bits),16):BigInt("0x"+String((value as {bits:string}).bits))}:Object.fromEntries(Object.entries(value).map(([key,item])=>[key,hydrate(item)]))):value;Object.assign(source,hydrate(source));const database=await semioMeshSnapshotToSqliteDatabase(source),bytes=await exportSqliteDatabase(database);expect(completeIndependentExtent(bytes)).toEqual({rows:item.rows,valueBytes:item.valueBytes,schemaBytes:completeSemanticContract.schemaBytes,tableWidths:completeSemanticContract.tableWidths});const limits={maxRows:item.rows,maxValueBytes:item.valueBytes,maxSchemaBytes:completeSemanticContract.schemaBytes,maxTables:10,maxColumns:27};expect(await semioMeshSnapshotToSqliteDatabase(source,limits)).toEqual(database);expect(await semioMeshSnapshotFromSqliteDatabase(await importSqliteDatabase(bytes),limits)).toEqual(source);
 for(const short of[{...limits,maxRows:item.rows-1},{...limits,maxValueBytes:item.valueBytes-1},{...limits,maxSchemaBytes:limits.maxSchemaBytes-1},{...limits,maxTables:9},{...limits,maxColumns:26}]){await expect(semioMeshSnapshotToSqliteDatabase(source,short)).rejects.toThrow();await expect(semioMeshSnapshotFromSqliteDatabase(database,short)).rejects.toThrow();}
 }console.log("[DEBUG] Semio Mesh independently measured Native matched full and empty roles through all5 copied limits");
});

