const input:SemioKitSnapshot={schema:"stdio.semio.kit",types:[{id:f.typeId,name:"Grüße\u0000世界",category:""}],designs:[{id:f.designId,name:"layout",pieces:f.pieceIds.map(id=>({id,typeId:f.typeId,transform:transform()})),connections:[{id:f.connectionId,connectingPieceId:f.pieceIds[0]!,connectingPort:f.ports[0]!,connectedPieceId:f.pieceIds[1]!,connectedPort:f.ports[1]!}]},{id:"empty",name:"",pieces:[],connections:[]}],objects:f.objectChildIds.map(id=>child(id,"object")),models:[child(f.modelChildId,"model")],properties:child(f.valueChildId,"value"),representations:[{target:target(),pin:{kind:"head"},role:f.typeId},{target:target(),pin:{kind:"checkpoint",id:f.checkpointId},role:f.typeId},{target:target(),pin:{kind:"snapshot",blob:{hash:f.blobHash,size:BigInt(f.blobSize),mediaType:f.blobMediaType}},role:f.typeId}]};
test("Semio Kit independent piece joins and exact unsigned64 blob pin edit",async()=>{expect(SEMIO_KIT_SQLITE_SCHEMA).toBe(await Bun.file(new URL("../🗄️.sql",import.meta.url)).text());const db=Database.deserialize(await exportSqliteDatabase(await semioKitSnapshotToSqliteDatabase(input)));try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query(f.query).all()).toHaveLength(1);expect(await semioKitSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(input);db.query("UPDATE semio_kit_blob SET size='9007199254740993'").run();const expected=structuredClone(input);const pin=expected.representations[2]!.pin;if(pin.kind!=="snapshot")throw Error("fixture pin");pin.blob.size=9007199254740993n;expect(await semioKitSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(expected);}finally{db.close();}});
test("Semio Kit exact placement states, relationship integrity and controls",async()=>{for(const hex of f.float64Bits){const s=structuredClone(input),word={bits:BigInt("0x"+hex)};s.designs[0]!.pieces[0]!.transform={translation:{x:word,y:word,z:word},rotation:{x:word,y:word,z:word,w:word},scale:{x:word,y:word,z:word}};const db=Database.deserialize(await exportSqliteDatabase(await semioKitSnapshotToSqliteDatabase(s)));try{expect(await semioKitSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(s);}finally{db.close();}}const d=await semioKitSnapshotToSqliteDatabase(input);for(const mutate of [(x:any)=>x.tables[3].rows[0].values[4]=99n,(x:any)=>x.tables[4].rows[0].values[4]=99n,(x:any)=>x.tables[5].rows[0].values[2]="foreign.artifact",(x:any)=>x.tables[9].rows[0].values[6]="unexpected",(x:any)=>x.tables[10].rows[0].values[2]="018446744073709551615"]){const x=structuredClone(d);mutate(x);await expect(semioKitSnapshotFromSqliteDatabase(x)).rejects.toThrow();}await expect(semioKitSnapshotToSqliteDatabase(input,{maxRows:1})).rejects.toThrow();await expect(semioKitSnapshotFromSqliteDatabase(d,{maxValueBytes:1})).rejects.toThrow();const c=new AbortController();c.abort();await expect(semioKitSnapshotFromSqliteDatabase(d,{signal:c.signal})).rejects.toThrow();const empty:SemioKitSnapshot={schema:"stdio.semio.kit",types:[],designs:[],objects:[],models:[],representations:[]};expect(await semioKitSnapshotFromSqliteDatabase(await semioKitSnapshotToSqliteDatabase(empty))).toEqual(empty);});

test("Semio kit distinct local child aliases preserve independent target identities",async()=>{for(const alias of f.distinctAliases){const s=structuredClone(input);s.objects[0]={childId:alias.childId,target:{artifactId:alias.artifactId,dialect:{artifactKind:"s.stdio.semio",standard:"v1",subset:"object"}}};const db=Database.deserialize(await exportSqliteDatabase(await semioKitSnapshotToSqliteDatabase(s)));try{expect(db.query("SELECT child_id,artifact_id FROM semio_kit_object_child JOIN semio_kit_reference ON target_reference_id=semio_kit_reference.id WHERE ordinal=0").get()).toEqual({child_id:alias.childId,artifact_id:alias.artifactId});expect(await semioKitSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(s);}finally{db.close();}}});

