import {Database} from "bun:sqlite";
import {expect,test} from "bun:test";
import f from "../🧫️fixtures/🔣️.json";
import type {SemioBrepSnapshot,BrepCurve,BrepCurve2,BrepSurface} from "../../../../🧬️schema/📸️snapshot/🟦️.ts";
import {SEMIO_BREP_SQLITE_SCHEMA,semioBrepSnapshotToSqliteDatabase,semioBrepSnapshotFromSqliteDatabase} from "../🟦️.ts";
import {binary64,exportSqliteDatabase,importSqliteDatabase} from "@semio-tech/framework";
const p3=()=>({x:binary64(1),y:binary64(2),z:binary64(3)}),axis=()=>({x:binary64(0),y:binary64(0),z:binary64(1)}),p2=()=>({x:binary64(1),y:binary64(2)}),knots=()=>f.knotValues.map(binary64);
const curves:BrepCurve[]=[{kind:"line",origin:p3(),direction:axis()},{kind:"circle",center:p3(),axis:axis(),radius:binary64(2.5)},{kind:"ellipse",center:p3(),axis:axis(),radiusMajor:binary64(3.5),radiusMinor:binary64(1.25)},{kind:"nurbs",controlPoints:[p3(),axis()],weights:[binary64(1),binary64(0.5)],degree:1,knots:knots()}],pcurves:BrepCurve2[]=[{kind:"line",origin:p2(),direction:p2()},{kind:"circle",center:p2(),radius:binary64(2.5)},{kind:"ellipse",center:p2(),xAxis:p2(),radiusMajor:binary64(3.5),radiusMinor:binary64(1.25)},{kind:"nurbs",controlPoints:[p2(),p2()],weights:[binary64(1),binary64(0.5)],degree:1,knots:knots()}],surfaces:BrepSurface[]=[{kind:"plane",origin:p3(),normal:axis()},{kind:"cylinder",origin:p3(),axis:axis(),radius:binary64(2.5)},{kind:"cone",origin:p3(),axis:axis(),radius:binary64(2.5),halfAngle:binary64(0.25)},{kind:"sphere",center:p3(),radius:binary64(2.5)},{kind:"torus",center:p3(),axis:axis(),majorRadius:binary64(3.5),minorRadius:binary64(1.25)},{kind:"nurbs",controlPoints:[p3(),axis()],weights:[binary64(1),binary64(0.5)],uCount:1,vCount:2,degreeU:0,degreeV:1,knotsU:[binary64(0),binary64(1)],knotsV:knots()}];
const input:SemioBrepSnapshot={schema:f.schema,nextLabel:BigInt(f.nextLabel),vertices:[{id:f.vertexIds[0]!,point:p3(),tol:binary64(0.001)},{id:f.vertexIds[1]!,point:axis(),tol:binary64(0.002)}],edges:curves.map((curve,i)=>({id:"e"+i,startVertex:f.vertexIds[0]!,endVertex:f.vertexIds[1]!,curve,tol:binary64(0.003)})),loops:[{id:"loop",edges:curves.map((_,i)=>({edge:"e"+i,orientation:i%2===0}))},{id:"inner",edges:[]}],faces:surfaces.map((surface,i)=>({id:"f"+i,outerLoop:"loop",innerLoops:["inner"],surface,orientation:i%2===0,tol:binary64(0.004)})),shells:[{id:"shell",faces:surfaces.map((_,i)=>({face:"f"+i,orientation:i%2===0}))}],solids:[{id:"solid",shells:[{shell:"shell",isVoid:false},{shell:"shell",isVoid:true}]}],coedges:pcurves.map((pcurve,i)=>({id:"c"+i,edge:"e"+i,forward:i%2===0,pcurve,prange:[binary64(-1),binary64(2)],loopId:"loop",next:"c"+((i+1)%4),prev:"c"+((i+3)%4)}))};
test("quick::Semio BRep all analytic/NURBS variants, exact labels and independent edits",async()=>{expect(SEMIO_BREP_SQLITE_SCHEMA).toBe(await Bun.file(new URL("../🗄️.sql",import.meta.url)).text());const db=Database.deserialize(await exportSqliteDatabase(await semioBrepSnapshotToSqliteDatabase(input)));try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query(f.query).all()).toEqual(f.curveKinds.map(kind=>({start:f.vertexIds[0],end:f.vertexIds[1],kind})));expect(await semioBrepSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(input);db.query("UPDATE semio_brep_document SET next_label='18446744073709551614'").run();expect((await semioBrepSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).nextLabel).toBe(18446744073709551614n);}finally{db.close();}for(const hex of f.float64Bits){const s=structuredClone(input),word={bits:BigInt("0x"+hex)};s.vertices[0]!.point.x=word;s.coedges[0]!.prange=[word,word];const curve=s.edges[3]!.curve;if(curve.kind!=="nurbs")throw Error("fixture NURBS");curve.weights[0]=word;expect(await semioBrepSnapshotFromSqliteDatabase(await importSqliteDatabase(await exportSqliteDatabase(await semioBrepSnapshotToSqliteDatabase(s))))).toEqual(s);}},30000);
test("quick::Semio BRep literal topology storage, geometry shape and resource controls",async()=>{const d=await semioBrepSnapshotToSqliteDatabase(input);for(const mutate of[(x:any)=>x.tables[2].rows[0].values[4]=999n,(x:any)=>x.tables[5].rows[0].values[10]=999n,(x:any)=>x.tables[5].rows[0].values[11]=1n,(x:any)=>x.tables[12].rows[0].values[14]=1,(x:any)=>x.tables[21].rows[0].values[2]=99n,(x:any)=>x.tables[0].rows[0].values[2]="018446744073709551615",(x:any)=>x.tables[2].rows[1].values[6]=x.tables[2].rows[0].values[6]]){const x=structuredClone(d);mutate(x);await expect(semioBrepSnapshotFromSqliteDatabase(x)).rejects.toThrow();}await expect(semioBrepSnapshotToSqliteDatabase(input,{maxRows:1})).rejects.toThrow();await expect(semioBrepSnapshotFromSqliteDatabase(d,{maxValueBytes:1})).rejects.toThrow();const c=new AbortController();c.abort();await expect(semioBrepSnapshotFromSqliteDatabase(d,{signal:c.signal})).rejects.toThrow();},30000);

