test("Semio Model independent graph joins and edited typed properties",async()=>{expect(SEMIO_MODEL_SQLITE_SCHEMA).toBe(await Bun.file(new URL("../🗄️.sql",import.meta.url)).text());const db=Database.deserialize(await exportSqliteDatabase(await semioModelSnapshotToSqliteDatabase(input)));try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query(f.query).all()).toHaveLength(6);expect(await semioModelSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(input);db.query("UPDATE semio_model_property SET text_value='independent' WHERE id=1").run();const edited=structuredClone(input);edited.elements[0]!.psets[0]!.properties[0]!.value={kind:"text",value:"independent"};expect(await semioModelSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(edited);}finally{db.close();}});
test("quick::Semio Model IEEE states, hierarchy cycles and exact variant fields",async()=>{for(const hex of f.float64Bits){const s=structuredClone(input),word={bits:BigInt("0x"+hex)};s.spatial[0]!.placement={translation:{x:word,y:word,z:word},rotation:{x:word,y:word,z:word,w:word},scale:{x:word,y:word,z:word}};s.elements[0]!.psets[0]!.properties[1]!.value={kind:"number",value:word};const db=Database.deserialize(await exportSqliteDatabase(await semioModelSnapshotToSqliteDatabase(s)));try{expect(await semioModelSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(s);}finally{db.close();}}const d=await semioModelSnapshotToSqliteDatabase(input);for(const mutate of[(x:any)=>x.tables[2].rows[0].values[3]=4n,(x:any)=>x.tables[3].rows[0].values[2]="unexpected",(x:any)=>x.tables[5].rows[0].values[2]="unexpected",(x:any)=>x.tables[7].rows[0].values[7]=1n,(x:any)=>x.tables[8].rows[0].values[6]=999n]){const x=structuredClone(d);mutate(x);await expect(semioModelSnapshotFromSqliteDatabase(x)).rejects.toThrow();}const cycle=structuredClone(input);cycle.spatial[0]!.parentId="s3";await expect(semioModelSnapshotToSqliteDatabase(cycle)).rejects.toThrow();await expect(semioModelSnapshotToSqliteDatabase(input,{maxRows:1})).rejects.toThrow();await expect(semioModelSnapshotFromSqliteDatabase(d,{maxValueBytes:1})).rejects.toThrow();const c=new AbortController();c.abort();await expect(semioModelSnapshotFromSqliteDatabase(d,{signal:c.signal})).rejects.toThrow();},30000);

test("Semio Model native construction frontier independently preserves duplicate property keys and empty text",async()=>{const count=f.nativeAdmission.collectionItems,s=structuredClone(input);s.spatial=[];s.elements=[{id:"element",class:{kind:"wall"},placement:placement(),geometry:{kind:"none"},spatialId:null,psets:[{name:"",properties:Array.from({length:count},()=>({key:"",value:{kind:"text",value:""}}))}]}];s.relations=[];const db=Database.deserialize(await exportSqliteDatabase(await semioModelSnapshotToSqliteDatabase(s)));try{expect(db.query("SELECT count(*) AS n FROM semio_model_property").get()).toEqual({n:count});expect(db.query("SELECT property_key,text_value FROM semio_model_property WHERE ordinal=?").get(f.nativeAdmission.cancelAfter)).toEqual({property_key:"",text_value:""});expect(await semioModelSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(s);}finally{db.close();}});

